function StatusIcon({ status, className }: { status: string; className?: string }) {
  const Icon = (() => {
    switch (status) {
      case "completed":
      case "complete":
        return CheckCircle2
      case "in_progress":
      case "incomplete":
        return Clock
      case "blocked":
        return XCircle
      default:
        return GitCommit
    }
  })()
  return <Icon className={className} />
}

